___CSS_LOADER_EXPORT___.push([module.id, "ul[data-v-306a3589]{margin-top:.6rem}ul li[data-v-306a3589]{position:relative}ul li[data-v-306a3589]:before{border:1px solid #000;border-radius:50%;content:\"\";height:10px;left:-20px;position:absolute;top:15px;width:10px}ul li.hadChild>.cate>.ca_name[data-v-306a3589]{font-weight:700}ul li.hadChild[data-v-306a3589]:before{background:#000}ul li button[data-v-306a3589]{border-width:0;line-height:12px}ul li .cate[data-v-306a3589]{cursor:pointer}ul li .cate .ca_name[data-v-306a3589]{border:2px dashed #fff;display:inline-block;padding:8px 0}ul li .cate .hd_menu[data-v-306a3589]{display:inline-block;position:relative;top:-2px}ul li .row[data-v-306a3589]{padding:2.5px 0}ul li .cate:focus .ca_name[data-v-306a3589]{background-color:#f0f0f0;border-color:#262b57;border-radius:5px}.slide-fade-enter-active[data-v-306a3589]{transition:all .1s ease}.slide-fade-leave-active[data-v-306a3589]{transition:all .2s cubic-bezier(1,.5,.8,1)}.slide-fade-enter[data-v-306a3589],.slide-fade-leave-to[data-v-306a3589]{opacity:0;transform:translateX(10px)}", "",{"version":3,"sources":["webpack://./resources/js/views/admin/shop/category/TreeView.vue"],"names":[],"mappings":"AAqIA,oBAAA,gBAAA,CACA,uBAAA,iBAAA,CACA,8BAEA,qBAAA,CAAA,iBAAA,CAAA,UAAA,CAAA,WAAA,CADA,UAAA,CAAA,iBAAA,CAAA,QAAA,CACA,UACA,CACA,+CAAA,eAAA,CACA,uCAAA,eAAA,CACA,8BAAA,cAAA,CAAA,gBAAA,CACA,6BAAA,cAAA,CACA,sCAAA,sBAAA,CAAA,oBAAA,CAAA,aAAA,CACA,sCAAA,oBAAA,CAAA,iBAAA,CAAA,QAAA,CAEA,4BAAA,eAAA,CACA,4CAAA,wBAAA,CAAA,oBAAA,CAAA,iBAAA,CAEA,0CACA,uBACA,CACA,0CACA,0CACA,CACA,yEAGA,SAAA,CADA,0BAEA","sourcesContent":["<template>\r\n    <draggable v-show=\"this.depth == 1 ? true : this.isOpen\" :list=\"cate\" handle=\".ca_move\" @change=\"sortUpdate\" tag=\"ul\">\r\n        <li v-for=\"(ca, i) in cate\" :key=\"i\" :index=\"i\" :class=\"{hadChild: ca.hasChild}\">\r\n            <div class=\"cate\"\r\n                v-if=\"!ca.update\"\r\n                :tabindex=\"i\"\r\n                @mousedown.right =\"showHiddenMenu(ca, $event)\"\r\n                @contextmenu.prevent\r\n                @blur=\"hideHiddenMenu(ca)\"\r\n            >\r\n                <div class=\"ca_name\" @click=\"clickCate(ca)\">{{ca.ca_name}} <span v-if=\"ca.hasChild\">[{{ subOpen ? '-' : '+' }}]</span></div>\r\n\r\n                <transition name=\"slide-fade\">\r\n                    <div class=\"hd_menu\" v-if=\"ca.showMenu\">\r\n                        <b-button variant=\"primary\" size=\"sm\" class=\"ca_move\" v-b-tooltip.hover title=\"순서 변경\"><b-icon icon=\"arrow-down-up\"></b-icon></b-button>\r\n                        <b-button variant=\"info\" size=\"sm\" v-if=\"!ca.hasChild\" @click=\"makeSub(ca)\" v-b-tooltip.hover title=\"하위 카테고리 생성\"><b-icon icon=\"diagram3-fill\"></b-icon></b-button>\r\n                        <b-button variant=\"warning\" size=\"sm\" @click=\"update(ca)\" v-b-tooltip.hover title=\"이름 변경\"><b-icon icon=\"tools\"></b-icon></b-button>\r\n                        <b-button variant=\"danger\" size=\"sm\" @click=\"isDestroy(ca.ca_id, i)\" v-b-tooltip.hover title=\"삭제\"><b-icon icon=\"trash\"></b-icon></b-button>\r\n                    </div>\r\n                </transition>\r\n            </div>\r\n            <b-row>\r\n                <b-col lg=\"8\" md=\"10\" cols=\"12\" class=\"py-1\">\r\n                    <input-update v-if=\"ca.update\" :ca=\"ca\"></input-update>\r\n                </b-col>\r\n            </b-row>\r\n\r\n            <tree-view v-if=\"ca.subCate\" ref=\"childCate\"\r\n                :key=\"ca.ca_id\"         :cate=\"ca.subCate\"\r\n                :ca_papa=\"ca.ca_id\"     :depth=\"depth+1\"\r\n                :isOpen=\"ca.sub_show\"   :parent=\"ca\"\r\n                @get-sub=\"getSub\"       @make-sube=\"makeSub\">\r\n            </tree-view>\r\n        </li>\r\n        \r\n        <li>\r\n            <b-row>\r\n                <b-col lg=\"8\" md=\"10\" cols=\"12\" class=\"py-1\">\r\n                    <input-insert :cate=\"cate\" :ca_papa=\"ca_papa\" :depth=\"depth\" @recount=\"recount\"></input-insert>\r\n                </b-col>\r\n            </b-row>\r\n        </li>\r\n    </draggable>\r\n</template>\r\n\r\n<script>\r\nimport ax from '@/api/http';\r\nimport draggable from 'vuedraggable';\r\nexport default {\r\n    name: \"TreeView\", // recursive 하기위해서 필요함. 없으면 error\r\n    components: {\r\n        draggable,\r\n        'InputInsert': () => import('@/views/admin/shop/category/InputInsert.vue'),\r\n        'InputUpdate': () => import('@/views/admin/shop/category/InputUpdate.vue'),\r\n    },\r\n    props:['isOpen', 'cate', 'depth', 'ca_papa', 'parent'],\r\n    data() {\r\n        return {\r\n            subOpen: false,\r\n        };\r\n    },\r\n    watch: {\r\n        comment_mode: function(newVal, oldVal) { // watch it\r\n            this.setBoContent();\r\n        },\r\n    },\r\n    computed: {\r\n\r\n    },\r\n    methods: {\r\n        clickCate(ca) {\r\n            if (ca.hasChild) {\r\n                this.openSwitch(ca);\r\n                if (!ca.hasOwnProperty('subCate')) this.getSub(ca);\r\n            } else {\r\n                if (ca.sub_show && !ca.hasChild && !ca.subCate.length) {\r\n                    //  자식 카테고리 없고 인풋창만 보일때\r\n                    //  ca.subCate 삭제\r\n                    this.$delete(ca, 'subCate');\r\n                    this.openSwitch(ca);\r\n                }\r\n            }\r\n        },\r\n        openSwitch: function (ca) { this.$set(ca, 'sub_show', !ca.sub_show); },\r\n        makeSub(ca) { this.$set(ca, 'subCate', []); this.openSwitch(ca); },\r\n        getSub(ca) { this.$emit('get-sub', ca); },\r\n        showHiddenMenu(ca, e) { this.$set(ca, 'showMenu', true); e.target.focus(); },\r\n        hideHiddenMenu(ca) { setTimeout(() => { this.$set(ca, 'showMenu', false); }, 1000); },\r\n        recount(){ this.$set(this.parent, 'hasChild', this.cate.length?true:false); },\r\n        update(ca) { this.$set(ca, 'update', true); },\r\n        isDestroy(ca_id, idx) {\r\n            this.$bvModal.msgBoxConfirm( \"삭제 하시겠습니까?\",\r\n                Object.assign({\r\n                    title: '삭제 확인 안내'\r\n                }, this.ConfirmModal)\r\n            ).then(value => {\r\n                if(value) this.coDestroy(ca_id, idx);\r\n            }).catch(err => { /* An error occurred */ });\r\n        },\r\n        async coDestroy(ca_id, idx) {\r\n            try {\r\n                let frm = new FormData();\r\n                frm.append(\"_method\", 'DELETE');\r\n                const res = await ax.post(`/api/admin/shop/category/${ca_id}`, frm);\r\n                if (res && res.status === 200) {\r\n                    Notify.toast('success', '삭제');\r\n                    this.$delete(this.parent.subCate, idx);\r\n                    this.recount();\r\n                }\r\n            } catch (e) { Notify.consolePrint(e); }\r\n        },\r\n\r\n        async sortUpdate(e) {\r\n            try {\r\n                const res = await ax.post('/api/admin/shop/category/set_seq', {\r\n                    ca_seq:e.moved.newIndex,\r\n                    old_ca_seq:e.moved.oldIndex,\r\n                    ca_papa:e.moved.element.ca_papa,\r\n                });\r\n                if (res && res.status === 200) Notify.toast('success', '순서 변경 완료');\r\n            } catch (e) { Notify.consolePrint(e); }\r\n        },\r\n    },\r\n    directives: {\r\n        focus: { inserted (el) { el.focus() } }\r\n    },\r\n    mounted() {\r\n        console.log(this.depth);\r\n    },\r\n}\r\n</script>\r\n\r\n<style lang=\"css\" scoped>\r\nul { margin-top:0.6rem; }\r\nul li { position:relative;  }\r\nul li:before {\r\n    position:absolute; top:15px; left:-20px;\r\n    content:\"\"; width:10px; height:10px; border:1px solid black; border-radius:50%\r\n}\r\nul li.hadChild > .cate > .ca_name { font-weight:bold; }\r\nul li.hadChild:before { background:black; }\r\nul li button { border-width:0; line-height:12px; }\r\nul li .cate { cursor:pointer; }\r\nul li .cate .ca_name { display:inline-block; padding:8px 0; border:2px dashed #FFF; }\r\nul li .cate .hd_menu { display:inline-block; position:relative; top:-2px; }\r\n/* #adm_category ul li .cate .hd_menu button { padding:0.2rem 0.25rem; font-size:0.56rem; line-height:0; } */\r\nul li .row { padding:2.5px 0; }\r\nul li .cate:focus .ca_name { border-color:#262b57; border-radius:5px; background-color:#F0F0F0; }\r\n\r\n.slide-fade-enter-active {\r\n  transition: all .1s ease;\r\n}\r\n.slide-fade-leave-active {\r\n  transition: all .2s cubic-bezier(1.0, 0.5, 0.8, 1.0);\r\n}\r\n.slide-fade-enter, .slide-fade-leave-to\r\n/* .slide-fade-leave-active below version 2.1.8 */ {\r\n  transform: translateX(10px);\r\n  opacity: 0;\r\n}\r\n</style>\r\n"],"sourceRoot":""}]);
